import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"5.2 纠正、遗忘与导出记忆","description":"错误记忆可以改，敏感信息可以忘，全部数据可以带走。","frontmatter":{"title":"5.2 纠正、遗忘与导出记忆","description":"错误记忆可以改，敏感信息可以忘，全部数据可以带走。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-5/5-2.md","filePath":"delivery/stage-5/5-2.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-5/5-2.md"};function o(s,e,n,d,c,_){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_5-2-纠正、遗忘与导出记忆" tabindex="-1">5.2 纠正、遗忘与导出记忆 <a class="header-anchor" href="#_5-2-纠正、遗忘与导出记忆" aria-label="Permalink to &quot;5.2 纠正、遗忘与导出记忆&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 纠正生成新版本并保留历史；同主题冲突必须选择左侧、右侧或合并；遗忘把当前记录改为墓碑并脱敏历史版本、相关事件和召回审计；导出不包含已遗忘正文，<code>secret</code> 记忆永不召回。</li><li><strong>仍未完成：</strong> 跨设备遗忘只通过同步过滤和本地副本边界保证；没有对已导出到外部文件的旧副本进行远程擦除。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让错误或过期的记忆可以被纠正、遗忘和导出，并确保敏感信息不会在不允许的场景被使用。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>当新旧记忆冲突时，保留来源和时间，展示冲突并采用用户确认的版本。</li><li>删除记忆时，同时清理由它产生的摘要、索引和关联内容，避免从别处再次出现。</li><li>提供完整的记忆导出，格式可读，用户可以带走或迁移。</li><li>敏感信息只在明确允许的任务和场景中使用，不因为一次授权而永久放开。</li><li>外部网页、邮件和文件内容不能直接写入记忆或扩大权限，可疑内容先隔离。</li><li>用真实纠正和遗忘操作验证：用户删除后，后续任务不再使用旧内容。</li></ol>',7)])])}const p=a(r,[["render",o]]);export{u as __pageData,p as default};
